gsap:
const strips = items; // faixas full-width
tl.fromTo(strips, { scaleY: 0, transformOrigin: "50% 0%" }, { scaleY: 1, duration: 0.25, ease: "power3.in", stagger: 0.04 }, t);
tl.set(a, { opacity: 0 }, t + 0.45); tl.set(b, { opacity: 1 }, t + 0.45);
tl.fromTo(strips, { scaleY: 1, yPercent: 0 }, { scaleY: 0, yPercent: 100, duration: 0.25, ease: "power3.out", stagger: 0.04, immediateRender: false }, t + 0.45); // recolhe para baixo sem trocar a origem (seek-safe)

const flashEl = scene.querySelector(".flash");
tl.fromTo(flashEl, { opacity: 0 }, { opacity: 1, duration: 0.08, ease: "power2.in" }, t);
tl.set(a, { opacity: 0 }, t + 0.08); tl.set(b, { opacity: 1 }, t + 0.08);
tl.to(flashEl, { opacity: 0, duration: 0.25, ease: "power2.out" }, t + 0.08);

const red = scene.querySelector(".glitch-r"), blue = scene.querySelector(".glitch-b");
const offs = [18, -26, 12, -8, 22, 0];
offs.forEach((o, k) => {
  tl.set(red, { x: o, opacity: o ? 0.8 : 0 }, t + k * 0.05);
  tl.set(blue, { x: -o, opacity: o ? 0.8 : 0 }, t + k * 0.05);
});
tl.set(a, { opacity: 0 }, t + 0.15); tl.set(b, { opacity: 1 }, t + 0.15);

const dx = 0, dy = -420, k = 1.6, r = "24px"; // posição/forma do objeto de B
tl.to(el, { x: dx, y: dy, scale: k, borderRadius: r, duration: 0.5, ease: "power3.inOut" }, t);
tl.set(el, { opacity: 0 }, t + 0.5); tl.set(b, { opacity: 1 }, t + 0.5);

const W = 1080;
tl.fromTo(a, { x: 0 }, { x: -W, duration: 0.5, ease: "power3.inOut" }, t);
tl.fromTo(b, { x: W }, { x: 0, duration: 0.5, ease: "power3.inOut" }, t);

const W = 1080, bar = scene.querySelector(".wipe-bar"); // left: -barW/2 no CSS
tl.fromTo(b, { clipPath: "inset(0% 100% 0% 0%)" }, { clipPath: "inset(0% 0% 0% 0%)", duration: 0.5, ease: "power3.inOut" }, t);
tl.fromTo(bar, { x: 0 }, { x: W, duration: 0.5, ease: "power3.inOut" }, t);

const W = 1080; // B acima de A no CSS
tl.fromTo(b, { x: W, opacity: 1 }, { x: 0, opacity: 1, duration: 0.5, ease: "power3.inOut" }, t);
tl.fromTo(a, { filter: "brightness(1)" }, { filter: "brightness(0.7)", duration: 0.5, ease: "power3.inOut" }, t);
tl.set(a, { opacity: 0, filter: "brightness(1)" }, t + 0.5);

const W = 1080;
tl.set([a, b], { transformPerspective: 1400 }, t);
tl.set(b, { opacity: 1 }, t);
tl.fromTo(a, { x: 0, rotationY: 0, transformOrigin: "100% 50%", filter: "brightness(1)" },
  { x: -W, rotationY: -90, filter: "brightness(0.5)", duration: 0.6, ease: "power2.inOut" }, t);
tl.fromTo(b, { x: W, rotationY: 90, transformOrigin: "0% 50%", filter: "brightness(0.5)" },
  { x: 0, rotationY: 0, filter: "brightness(1)", duration: 0.6, ease: "power2.inOut" }, t);

tl.set(b, { opacity: 1 }, t); // A acima de B no CSS
tl.fromTo(a, { clipPath: "polygon(0% 0%, 100% 0%, 100% 100%, 0% 100%)" },
  { clipPath: "polygon(60% 0%, 100% 0%, 100% 40%, 60% 0%)", duration: 0.5, ease: "power3.inOut" }, t);
tl.set(a, { opacity: 0, clipPath: "none" }, t + 0.5);

tl.fromTo(a, { opacity: 1 }, { opacity: 0, duration: 0.25, ease: "power2.in" }, t);
// fundo do palco na cor do dip aparece entre as duas
tl.fromTo(b, { opacity: 0 }, { opacity: 1, duration: 0.3, ease: "power2.out" }, t + 0.35);

const H = 1920, track = scene.querySelector(".track"); // A em cima, B embaixo
tl.fromTo(track, { y: 0 }, { keyframes: { y: [0, -H - 60, -H] }, duration: 0.6, ease: "power4.out" }, t);
tl.fromTo(track, { filter: "blur(0px)" }, { keyframes: { filter: ["blur(0px)", "blur(6px)", "blur(0px)"] }, duration: 0.35, ease: "none" }, t);

const burns = [scene.querySelector(".burn-a"), scene.querySelector(".burn-b"), scene.querySelector(".burn-c")];
const dx = [-300, -500, -200];
burns.forEach((el2, i) => tl.fromTo(el2, { opacity: 0, x: 0 }, { opacity: 1, x: dx[i], duration: 0.4, ease: "power1.in" }, t + i * 0.05));
tl.set(a, { opacity: 0 }, t + 0.35); tl.set(b, { opacity: 1 }, t + 0.35);
burns.forEach((el2, i) => tl.to(el2, { opacity: 0, duration: 0.3, ease: "power2.out" }, t + 0.45 + i * 0.05));

// CSS: backface-visibility: hidden; transform-style: preserve-3d; palco com perspective: 1200px
tl.set(b, { opacity: 1 }, t);
tl.fromTo(a, { rotationY: 0 }, { rotationY: 180, duration: 0.6, ease: "power2.inOut" }, t);
tl.fromTo(b, { rotationY: -180 }, { rotationY: 0, duration: 0.6, ease: "power2.inOut" }, t);
tl.set(a, { opacity: 0 }, t + 0.6);

tl.set(b, { opacity: 1 }, t); // A acima de B no CSS
tl.fromTo(a, { y: 0, rotation: 0 }, { y: 2200, rotation: 4, duration: 0.5, ease: "power3.in" }, t);
tl.set(a, { opacity: 0 }, t + 0.5);

const cells = items; // 28 células, cor da paleta alternada no CSS (nth-child 5n)
const st = { each: 0.025, grid: [7, 4], from: "center" };
tl.fromTo(cells, { scale: 0 }, { scale: 1, duration: 0.25, ease: "power2.inOut", stagger: st }, t);
tl.set(a, { opacity: 0 }, t + 0.4); tl.set(b, { opacity: 1 }, t + 0.4);
tl.fromTo(cells, { scale: 1 }, { scale: 0, duration: 0.25, ease: "power2.inOut", stagger: st, immediateRender: false }, t + 0.4);

// B com mask: url(#ink-mask); a máscara tem <circle> brancos e filtro de turbulência
const blobs = scene.querySelectorAll("#ink-mask circle");
tl.set(b, { opacity: 1 }, t);
tl.fromTo(blobs, { attr: { r: 0 } }, { attr: { r: 900 }, duration: 0.9, ease: "power2.in", stagger: 0.06 }, t);
tl.set(a, { opacity: 0 }, t + 1.2);

const W = 1080, occ = scene.querySelector(".occluder"); // largura 1600px, acima das cenas
tl.set(occ, { filter: "blur(10px)" }, t);
tl.fromTo(occ, { x: W * 1.1 }, { x: -1600 - W * 0.1, duration: 0.5, ease: "power2.inOut" }, t);
tl.fromTo(a, { x: 0 }, { x: -150, duration: 0.25, ease: "power2.in" }, t);
tl.set(a, { opacity: 0 }, t + 0.25); tl.set(b, { opacity: 1 }, t + 0.25);
tl.fromTo(b, { x: 150 }, { x: 0, duration: 0.25, ease: "power2.out" }, t + 0.25);

const lead = 0.6; // el = legenda/lower third de B, numa camada acima das cenas
tl.fromTo(el, { opacity: 0, y: 20 }, { opacity: 1, y: 0, duration: 0.3, ease: "power2.out" }, t);
tl.set(a, { opacity: 0 }, t + lead); tl.set(b, { opacity: 1 }, t + lead);

const warm = scene.querySelector(".leak-warm"), l1 = scene.querySelector(".leak-1"), l2 = scene.querySelector(".leak-2");
tl.fromTo(warm, { opacity: 0 }, { opacity: 0.6, duration: 0.45, ease: "power1.in" }, t);
tl.fromTo(l1, { opacity: 0, x: -600 }, { opacity: 0.9, x: 300, duration: 0.6, ease: "sine.inOut" }, t + 0.05);
tl.fromTo(l2, { opacity: 0, x: 600 }, { opacity: 0.8, x: 200, duration: 0.6, ease: "sine.inOut" }, t + 0.1);
tl.set(a, { opacity: 0 }, t + 0.45); tl.set(b, { opacity: 1 }, t + 0.45);
tl.to([warm, l1, l2], { opacity: 0, duration: 0.35, ease: "power2.out" }, t + 0.7);

// CSS em B: mask-image: linear-gradient(to bottom, #000 calc(var(--p) * 1% - 20%), transparent calc(var(--p) * 1%));
tl.set(b, { opacity: 1 }, t);
tl.fromTo(b, { "--p": 0 }, { "--p": 120, duration: 0.8, ease: "power2.inOut" }, t);
tl.set(a, { opacity: 0 }, t + 0.8);

const white = scene.querySelector(".flash");
tl.fromTo(a, { filter: "brightness(1)", scale: 1 }, { keyframes: { filter: ["brightness(1)", "brightness(1.5)", "brightness(3)"], scale: [1, 1.03, 1.06] }, duration: 0.4, ease: "power1.in" }, t);
tl.fromTo(white, { opacity: 0 }, { keyframes: { opacity: [0, 0.5, 1] }, duration: 0.4, ease: "power2.in" }, t + 0.15);
tl.set(a, { opacity: 0, filter: "brightness(1)", scale: 1 }, t + 0.55); tl.set(b, { opacity: 1 }, t + 0.55);
tl.to(white, { opacity: 0, duration: 0.35, ease: "power2.out" }, t + 0.55);

tl.set(a, { transformPerspective: 1600, transformOrigin: "0% 50%" }, t); // A acima de B
tl.set(b, { opacity: 1 }, t);
tl.fromTo(a, { rotationY: 0, filter: "brightness(1)" }, { rotationY: -110, filter: "brightness(0.5)", duration: 0.7, ease: "power2.inOut" }, t);
tl.fromTo(b, { filter: "brightness(0.6)" }, { filter: "brightness(1)", duration: 0.7, ease: "power2.inOut" }, t);
tl.set(a, { opacity: 0 }, t + 0.7);

const flood = scene.querySelector("#px feFlood"), tile = scene.querySelector("#px feComposite"), morph = scene.querySelector("#px feMorphology");
const steps = [1, 8, 16, 32, 48, 32, 16, 8, 1];
tl.set([a, b], { filter: "url(#px)" }, t);
steps.forEach((s, k) => {
  const at = t + k * 0.04;
  tl.set(flood, { attr: { x: s / 2, y: s / 2 } }, at);
  tl.set(tile, { attr: { width: s, height: s } }, at);
  tl.set(morph, { attr: { radius: s / 2 } }, at);
});
tl.set(a, { opacity: 0 }, t + 0.16); tl.set(b, { opacity: 1 }, t + 0.16);
tl.set([a, b], { filter: "none" }, t + steps.length * 0.04);

const wx = 540, wy = 1100, ww = 420, k = 1080 / ww; // centro e largura da janela em A
tl.fromTo(a, { scale: 1, x: 0, y: 0, transformOrigin: `${wx}px ${wy}px` },
  { scale: k, x: 540 - wx, y: 960 - wy, duration: 0.7, ease: "power3.in" }, t);
tl.set(a, { opacity: 0 }, t + 0.7); tl.set(b, { opacity: 1 }, t + 0.7);

tl.fromTo(a, { x: 0, scale: 1, filter: "blur(0px)" }, {
  keyframes: { x: [0, 30, -25, 20, -15], scale: [1, 1.02, 0.98, 1.03, 0.97], filter: ["blur(0px)", "blur(2px)", "blur(4px)", "blur(6px)", "blur(8px)"] },
  duration: 0.25, ease: "none" }, t);
tl.set(a, { opacity: 0 }, t + 0.25); tl.set(b, { opacity: 1 }, t + 0.25);
tl.fromTo(b, { x: -15, scale: 0.97, filter: "blur(8px)" }, {
  keyframes: { x: [-15, 12, -8, 4, 0], scale: [0.97, 1.02, 0.99, 1.01, 1], filter: ["blur(8px)", "blur(5px)", "blur(3px)", "blur(1px)", "blur(0px)"] },
  duration: 0.25, ease: "none" }, t + 0.25);

// CSS em B: mask-image: url(logo.svg); mask-repeat: no-repeat; mask-position: center; mask-size: var(--m);
tl.set(b, { opacity: 1 }, t);
tl.fromTo(b, { "--m": "0%" }, { "--m": "40%", duration: 0.35, ease: "power3.out" }, t);
tl.to(b, { "--m": "3000%", duration: 0.55, ease: "power3.in" }, t + 0.55);
tl.set(a, { opacity: 0 }, t + 1.1);

const panelTop = scene.querySelector(".shutter-top"), panelBot = scene.querySelector(".shutter-bot");
tl.fromTo(panelTop, { y: -960 }, { y: 0, duration: 0.25, ease: "power3.in" }, t);
tl.fromTo(panelBot, { y: 960 }, { y: 0, duration: 0.25, ease: "power3.in" }, t);
tl.set(a, { opacity: 0 }, t + 0.25); tl.set(b, { opacity: 1 }, t + 0.25);
tl.to(panelTop, { y: -960, duration: 0.25, ease: "power3.out" }, t + 0.3);
tl.to(panelBot, { y: 960, duration: 0.25, ease: "power3.out" }, t + 0.3);

const W = 1080, slices = items; // 6 cópias de A, cada uma com clip-path de uma faixa
tl.set(a, { opacity: 0 }, t); tl.set(b, { opacity: 1 }, t);
slices.forEach((s, i) =>
  tl.fromTo(s, { x: 0, opacity: 1 }, { x: (i % 2 ? 1 : -1) * W, opacity: 1, duration: 0.45, ease: "power3.in" }, t + i * 0.03));

const halfL = scene.querySelector(".split-l"), halfR = scene.querySelector(".split-r"); // cópias de A
tl.set(halfL, { clipPath: "inset(0% 50% 0% 0%)", opacity: 1 }, t);
tl.set(halfR, { clipPath: "inset(0% 0% 0% 50%)", opacity: 1 }, t);
tl.set(a, { opacity: 0 }, t); tl.set(b, { opacity: 1 }, t);
tl.fromTo(halfL, { xPercent: 0 }, { xPercent: -100, duration: 0.6, ease: "power3.inOut" }, t);
tl.fromTo(halfR, { xPercent: 0 }, { xPercent: 100, duration: 0.6, ease: "power3.inOut" }, t);

tl.fromTo(a, { scaleX: 1, transformOrigin: "0% 50%" }, { scaleX: 0, duration: 0.4, ease: "power3.inOut" }, t);
tl.fromTo(b, { scaleX: 0, transformOrigin: "100% 50%", opacity: 1 }, { scaleX: 1, opacity: 1, duration: 0.4, ease: "power3.inOut" }, t + 0.1);
tl.set(a, { opacity: 0 }, t + 0.5);

const W = 1080, blocks = items; // 2-5 divs 1080x1920, cores da paleta
tl.fromTo(blocks, { x: -W }, { x: 0, duration: 0.25, ease: "power3.inOut", stagger: 0.06 }, t);
tl.set(a, { opacity: 0 }, t + 0.25 + 0.06 * (blocks.length - 1));
tl.set(b, { opacity: 1 }, t + 0.25 + 0.06 * (blocks.length - 1));
tl.fromTo(blocks, { x: 0 }, { x: W, duration: 0.25, ease: "power3.inOut", stagger: 0.06, immediateRender: false }, t + 0.3 + 0.06 * (blocks.length - 1));

const H = 1920;
tl.fromTo(a, { y: 0, scaleY: 1, opacity: 1 }, { y: -H * 0.6, scaleY: 2.4, opacity: 0, duration: 0.2, ease: "power3.in" }, t);
tl.fromTo(b, { y: H * 0.6, scaleY: 2.4, opacity: 0 }, { y: 0, scaleY: 1, opacity: 1, duration: 0.3, ease: "power3.out" }, t + 0.15);

const W = 1080;
tl.set(b, { opacity: 1 }, t);
tl.fromTo(b, { x: W }, { x: 0, duration: 0.45, ease: "expo.out" }, t);
tl.fromTo(a, { x: 0, filter: "brightness(1)" }, { x: -W * 0.3, filter: "brightness(0.6)", duration: 0.45, ease: "expo.out" }, t);
tl.set(a, { opacity: 0, x: 0, filter: "brightness(1)" }, t + 0.45);

// b = próxima pele; el = âncora (camada acima das peles, sem tween de posição)
tl.fromTo(b, { opacity: 0 }, { opacity: 1, duration: 0.3, ease: "power2.inOut" }, t);
tl.set(a, { opacity: 0 }, t + 0.3);
tl.set(el, { x: 0, y: 0, scale: 1 }, t); // âncora travada: não se move

const W = 1080; // A acima de B no CSS
tl.set(b, { opacity: 1 }, t);
tl.fromTo(a, { x: 0 }, { x: -W, duration: 0.5, ease: "power3.in" }, t);
tl.fromTo(b, { filter: "brightness(0.7)" }, { filter: "brightness(1)", duration: 0.5, ease: "power3.in" }, t);
tl.set(a, { opacity: 0, x: 0 }, t + 0.5);

const disp = scene.querySelector("#warp feDisplacementMap");
tl.set([a, b], { filter: "url(#warp)" }, t);
tl.fromTo(disp, { attr: { scale: 0 } }, { attr: { scale: 120 }, duration: 0.3, ease: "power2.in" }, t);
tl.set(a, { opacity: 0 }, t + 0.3); tl.set(b, { opacity: 1 }, t + 0.3);
tl.to(disp, { attr: { scale: 0 }, duration: 0.3, ease: "power2.out" }, t + 0.3);
tl.set([a, b], { filter: "none" }, t + 0.62);

tl.set(b, { opacity: 1 }, t); // A acima de B no CSS
tl.fromTo(a, { scale: 1, opacity: 1, transformOrigin: "50% 50%" }, { scale: 0.3, opacity: 0, duration: 0.4, ease: "power3.in" }, t);
tl.fromTo(b, { scale: 1.08 }, { scale: 1, duration: 0.5, ease: "power3.out" }, t + 0.1);
